// MANUAL FILE (not generated by HARIA). Safe across regenerations.
//
// Web-side user EntityModels that use real inheritance.
//
// The backend (TDM / Domain) has a single `Usuario` class with a `RolUsuario`
// enum attribute. HARIA's web authorization works with user classes and roles,
// so the web layer turns that enum into this hierarchy:
//
//     UsuarioModel (abstract)
//       └─ RegistradoModel
//            └─ ModeradorModel
//                 └─ AdministradorModel
//
// Each subclass adds its own role to the roles it inherits. An Administrador
// therefore also has Moderador and Registrado, so
// [Authorize(Roles = UserRoles.Moderador)] admits moderators and admins.
//
// UsuarioModelMapper (same folder) translates between these models and the
// backend Usuario / RolUsuario in both directions.
using WikiGames.Domain.Enums;
using WikiGames.Web.Utils.Security;

namespace WikiGames.Web.Models.Usuarios;

public abstract class UsuarioModel
{
    public int Id { get; init; }
    public string Name { get; init; } = string.Empty;
    public string Email { get; init; } = string.Empty;

    /// <summary>Backend enum value this subclass stands for.</summary>
    public abstract Rol Rol { get; }

    /// <summary>Name of the concrete web user class ("Registrado", "Moderador", "Administrador").</summary>
    public string UserClass => Rol.ToString();

    /// <summary>The roles granted to this class: its own role plus every inherited one.</summary>
    public virtual IReadOnlyCollection<string> Roles => [];
}

public class RegistradoModel : UsuarioModel
{
    public override Rol Rol => Rol.Registrado;
    public override IReadOnlyCollection<string> Roles => [.. base.Roles, UserRoles.Registrado];
}

public class ModeradorModel : RegistradoModel
{
    public override Rol Rol => Rol.Moderador;
    public override IReadOnlyCollection<string> Roles => [.. base.Roles, UserRoles.Moderador];
}

public sealed class AdministradorModel : ModeradorModel
{
    public override Rol Rol => Rol.Administrador;
    public override IReadOnlyCollection<string> Roles => [.. base.Roles, UserRoles.Administrador];
}
